      async function* () {
        yield new TextEncoder().encode('Ada\nLin\n')
      }
    )
    await tx.set('example:import', 'done')
    await tx.api.notifications.notify('example_ready', 'done')
  })
  console.log(await message.promise)
} finally {
  await pool.end()
}

